  PLACE_VALUE_HM: { key_step: 'The child says the place of a digit by counting from the ones place on the right, three places at a time, and names the group (ones, thousands, millions).', floor: ['Reads numbers to millions.', 'Which digit is in the thousands place in 4,215,683?', '5'], reps: ['a place value chart in groups of three', 'the number with commas', 'the number said aloud'], steps: ['Write the number under a chart with headings Ones, Thousands, Millions.', 'Each group has three places: hundreds, tens, ones.', 'Count from the right to find the place of the digit asked about.', 'Name the digit that sits in a place asked about.'], contexts: ['a county budget', 'phone lines in a region', 'people watching a match'], board: [['draw', 'Draw a chart with three groups and nine places. Write 305,000,200 in it.'], ['point', 'Point at the digit 3.', 'Which group is this digit in?'], ['pause', 'Wait for the child to name the place.']], mis: { M_COUNT_FROM_LEFT: [['starts from the left', 'the first place'], 'If you start counting from the left, does the ones place stay in the same box when the number gets longer?', 'The ones place is always on the right. Count from there.'], M_PLACE_SKIPPED_GROUP: [['ten millions', 'it is in millions'], 'How many places are in the millions group?', 'Each group has three places: hundreds, tens and ones of that group.'], M_ZERO_NOT_A_PLACE: [['skip the zero', 'zero is nothing'], 'If we take the zero away, does 4 stay in the same place?', 'A zero is a digit that holds its place.'] }, checks: [['In 407,530,918 which place is the digit 5 in?', 'hundred thousands', 'name a place'], ['In 82,305,614 which digit is in the hundred thousands place?', '3', 'find a digit from its place']] },
